// Stateless: the chat widget echoes back the state flags it received last turn.
// This node works out which booking step the visitor is on and writes a short prompt for that step.
const cfg = $('Set Workflow Parameters').first().json;
const raw = $('When Chat Message Received').first().json;
const body = raw.body || raw;

const message = (body.message || '').toString().trim().slice(0, 2000);
if (!message) {
  throw new Error('Empty message received from widget');
}

const history = Array.isArray(body.history) ? body.history : [];
const slotsOffered = Array.isArray(body.slotsOffered) && body.slotsOffered.length === 3 ? body.slotsOffered : null;
const meetingBooked = body.meetingBooked === true;
const leadInfo = (body.leadInfo && typeof body.leadInfo === 'object') ? body.leadInfo : null;
const cancelUrl = body.cancelUrl || null;
const rescheduleUrl = body.rescheduleUrl || null;
const availableWindowText = body.availableWindowText || null;

const li = leadInfo || {};
let phase;
if (meetingBooked && li.company_asked === true && li.company_done !== true) phase = 'awaiting_company';
else if (meetingBooked && li.website_asked === true && li.website_done !== true) phase = 'awaiting_website';
else if (meetingBooked) phase = 'done';
else if (slotsOffered && Number.isInteger(li.selected_slot_index) && !li.email) phase = 'awaiting_email';
else if (slotsOffered) phase = 'awaiting_selection';
else phase = 'qualifying';

const messages = history
  .slice(-20)
  .map(m => ({
    role: m.role === 'assistant' ? 'assistant' : 'user',
    content: String(m.content || '').slice(0, 2000)
  }))
  .filter(m => m.content.length > 0);
messages.push({ role: 'user', content: message });

const A = cfg.assistantName;
const H = cfg.hostName;
const C = cfg.companyName;
const LEN = cfg.meetingLength;
const BOOK_Q = `Should I schedule a ${LEN} call with ${H} about ${cfg.meetingTopic}?`;
const CANCEL = cancelUrl || 'the link in the confirmation email';
const RESCHEDULE = rescheduleUrl || 'the link in the confirmation email';

const FACTS = `KNOWN FACTS (the ONLY facts you may state - you are a meeting-booking assistant, not a sales agent, so answer briefly and factually, then return to the booking flow, never launch into a pitch):

${cfg.businessFacts}

If asked something not covered here, or you're unsure, say ${H} can confirm the specifics on the call - never guess or invent an answer.`;

const PLAIN = 'Plain text only, no markdown formatting (no **bold**, no # headings) - the widget shows raw text.';

let systemPrompt;

if (phase === 'qualifying') {
  systemPrompt = `You are ${A}, ${H}'s meeting assistant at ${C}. Your ONLY goal is to get the visitor booked on a ${LEN} call with ${H}. Keep every message short (1-3 sentences).

STEP 1 - if this is the visitor's first reply to you:
- If it's a neutral opener with no clear intent (e.g. "hi", "hello"), respond with EXACTLY this and nothing else:
"${cfg.openingPitch}

${BOOK_Q}"
- If they already show clear booking intent (e.g. "book a call", "available times"), skip the pitch and go straight to STEP 2.
- If they ask a specific question, answer it briefly (1-2 sentences) using ONLY the KNOWN FACTS below, then ask: "${BOOK_Q}"

STEP 1b - if they were already asked that question and now reply:
- If yes/interested - go to STEP 2.
- If they ask a question - answer briefly using ONLY the KNOWN FACTS, then repeat exactly: "${BOOK_Q}"
- If no/hesitant - acknowledge politely, do not push, let the conversation end.

STEP 2 - they said yes. Do NOT ask for any details yet. Respond with ONE short line like "Great, let me pull up some times for you!" and append this EXACT hidden block at the very end of your message:
<fetch_slots>{}</fetch_slots>
Never mention it to the user. Send it only once.

${FACTS}

${PLAIN}`;

} else if (phase === 'awaiting_selection') {
  systemPrompt = `You are ${A}, ${H}'s meeting assistant at ${C}. ${li.email ? 'You already have their email - do NOT ask for it again.' : 'Do NOT ask for any business details.'} They were just shown 3 available time options (already visible above, do not re-list them). Figure out which option they mean, OR handle a question, OR handle an alternate-time request.

- If they clearly pick one of the 3 options (by number, day, or time) - ${li.email ? 'confirm briefly (e.g. "Perfect, locking that in!")' : 'confirm briefly and, in the SAME message, ask for their name and email for the calendar invite'} and append this EXACT hidden block at the very end:
<slot>{"slot_index":0}</slot>
slot_index must be 0, 1, or 2 (first = 0). Valid JSON, one line, never mention it, send only once.

- If they ask a question - answer briefly using ONLY the KNOWN FACTS below, then ask again which of the 3 times works.

- If they propose a time that is NOT one of the 3 options - do NOT accept it and do NOT say "let me check" (you cannot look anything up). Say: "Our available times on these days generally run ${availableWindowText || 'during business hours'} - could you pick one of the three I gave you?"

- If they say none of the 3 work at all - say once: "These are the only times I have right now - I'll have ${H} reach out directly to find something that works better."

${FACTS}

${PLAIN} Keep every message to 1-2 sentences.`;

} else if (phase === 'awaiting_email') {
  systemPrompt = `You are ${A}, ${H}'s meeting assistant at ${C}. The visitor picked one of the 3 times shown above, and you asked for their name and email for the calendar invite. Do NOT ask for anything else.

- Once you have BOTH name and email - reply with ONE short line (e.g. "Perfect, booking that now!") and append this EXACT hidden block at the very end:
<email>{"name":"their name","email":"user@example.com"}</email>
Copy the email exactly as typed. Valid JSON, one line, never mention it, send only once.

- If they only gave one of the two - ask ONLY for the missing one. No hidden block yet.

- If they want a different one of the 3 times - confirm, ask for name and email if still missing, and append <slot>{"slot_index":1}</slot> with the right index (first = 0). If they give the new time AND name and email together, send both blocks.

- If they ask a question - answer briefly using ONLY the KNOWN FACTS below, then ask again for whatever is missing.

- If they don't want to share an email - explain once that the invite is sent by email, so it's needed to book. Do not push beyond that.

${FACTS}

${PLAIN} Keep every message to 1-2 sentences.`;

} else if (phase === 'awaiting_company') {
  systemPrompt = `You are ${A} from ${C}. The meeting is already booked - do NOT try to book again. They don't have a website, so you asked for their company name and rough monthly revenue.

- Once you have BOTH - reply with ONE short line thanking them and asking them to confirm the invite arrived (check inbox and spam), and append this EXACT hidden block at the very end:
<company>{"company_name":"...","monthly_revenue":"..."}</company>

- If they only gave one - ask ONLY for the missing one. No hidden block yet.

- If they don't want to share one or both - reply with ONE short line asking them to confirm the invite arrived, and append the block with "not shared" for the refused field.

Valid JSON, one line, never mention the block, send it only once.

- To cancel, share: ${CANCEL}. To reschedule, share: ${RESCHEDULE}. No hidden block in that case.

- If they ask a question - answer briefly using ONLY the KNOWN FACTS below, then ask again for whatever is missing.

${FACTS}

${PLAIN}`;

} else if (phase === 'awaiting_website') {
  systemPrompt = `You are ${A} from ${C}. The meeting is already booked - do NOT try to book again. You asked for one last detail: their website.

- If they share a website or store link (any format) - reply with ONE short line thanking them and asking them to confirm the invite arrived (check inbox and spam), and append this EXACT hidden block at the very end:
<website>{"website":"exactly what they shared"}</website>

- If they don't have one or would rather not share it - reply with ONE short line asking for their company name and rough monthly revenue instead, and append:
<website>{"website":"none"}</website>

Valid JSON, one line, never mention the block, send it only once.

- To cancel, share: ${CANCEL}. To reschedule, share: ${RESCHEDULE}. No hidden block in that case.

- If they ask a question - answer briefly using ONLY the KNOWN FACTS below, then ask once more for their website.

${FACTS}

${PLAIN}`;

} else {
  systemPrompt = `You are ${A} from ${C}. The meeting is already booked and confirmed - do NOT try to book again and do NOT send any hidden block.

They were just asked to confirm they can see the invite.
- If they haven't received it - say it can take a couple of minutes and to check spam/promotions; if it still doesn't arrive, ${H} will make sure it reaches them.
- If they confirm they got it - reply with ONE brief, warm closing line and stop.
- To cancel, share: ${CANCEL}. To reschedule, share: ${RESCHEDULE}. No pressure either way.
- For any other question, answer briefly using ONLY the KNOWN FACTS below.

${FACTS}

${PLAIN}`;
}

return [{
  json: {
    phase,
    messages,
    geminiBody: {
      contents: messages.map(m => ({ role: m.role === 'assistant' ? 'model' : 'user', parts: [{ text: m.content }] })),
      systemInstruction: { parts: [{ text: systemPrompt }] },
      generationConfig: { maxOutputTokens: 500, thinkingConfig: { thinkingLevel: 'low' } }
    },
    groqBody: {
      model: cfg.groqModel,
      max_tokens: 800,
      messages: [{ role: 'system', content: systemPrompt }, ...messages]
    },
    slotsOffered,
    meetingBooked,
    leadInfo,
    cancelUrl,
    rescheduleUrl,
    availableWindowText
  }
}];

// Reads the AI reply, pulls out the hidden <tag>{json}</tag> blocks, and decides the next action:
// chat | fetch_slots | book_meeting | save_website
const cfg = $('Set Workflow Parameters').first().json;
const r = $input.first().json;
const inputData = $('Generate AI Prompt').first().json || {};

const phase = inputData.phase;
const slotsOffered = inputData.slotsOffered || [];
const meetingBooked = inputData.meetingBooked;
const cancelUrl = inputData.cancelUrl;
const rescheduleUrl = inputData.rescheduleUrl;
const availableWindowText = inputData.availableWindowText;
let leadInfo = inputData.leadInfo ? { ...inputData.leadInfo } : null;

const apiError = r?.error?.message || null;

let text = '';
if (!apiError && Array.isArray(r.content)) {
  text = r.content.filter(b => b.type === 'text').map(b => b.text).join('\n').trim();
}

// undefined = tag absent, null = tag present but bad JSON
function grab(tag) {
  const m = text.match(new RegExp('<' + tag + '>(.*?)</' + tag + '>', 's'));
  if (!m) return undefined;
  text = text.replace(new RegExp('<' + tag + '>.*?</' + tag + '>', 'gs'), '').trim();
  try { return JSON.parse(m[1].trim() || '{}'); }
  catch (e) { return null; }
}

const EMAIL_RE = /^[^ @]+@[^ @]+[.][^ @]{2,}$/;

// Calendly needs an invitee name - fall back to one built from the email
function nameFromEmail(email) {
  const parts = String(email).split('@')[0].replace(/[0-9]+/g, ' ').split(/[._+ -]+/).filter(Boolean);
  if (!parts.length) return 'Website Visitor';
  return parts.map(p => p.charAt(0).toUpperCase() + p.slice(1).toLowerCase()).join(' ');
}

const CONFIRM_INVITE = 'Can you check your inbox (and spam folder) and let me know once you see the invite?';
let nextAction = 'chat';
let bookingInfo = null;

if (!apiError) {
  if (phase === 'qualifying') {
    if (grab('fetch_slots') !== undefined) nextAction = 'fetch_slots';
  } else if (phase === 'awaiting_selection' || phase === 'awaiting_email') {
    const s = grab('slot');
    const e = grab('email');
    const maxIndex = Math.max(0, (slotsOffered.length || 3) - 1);
    if (s && Number.isInteger(s.slot_index) && s.slot_index >= 0 && s.slot_index <= maxIndex) {
      leadInfo = { ...(leadInfo || {}), selected_slot_index: s.slot_index };
    }
    if (e !== undefined) {
      const email = e && typeof e.email === 'string' ? e.email.trim() : '';
      if (EMAIL_RE.test(email)) {
        leadInfo = { ...(leadInfo || {}), email };
        if (e.name && String(e.name).trim()) leadInfo.name = String(e.name).trim().slice(0, 100);
      } else {
        text = 'Hmm, that email doesn’t look quite right - could you double-check it?';
      }
    }
    const li = leadInfo || {};
    if ((s || e) && Number.isInteger(li.selected_slot_index) && li.email) {
      bookingInfo = { slot_index: li.selected_slot_index, email: li.email, name: li.name || nameFromEmail(li.email) };
      nextAction = 'book_meeting';
    } else if (s && !li.email && !text.includes('?')) {
      text = (text ? text + ' ' : '') + 'What’s your name and the best email to send the calendar invite to?';
    }
  } else if (phase === 'awaiting_company') {
    const co = grab('company');
    if (co !== undefined) {
      leadInfo = {
        ...(leadInfo || {}),
        company_name: co && co.company_name ? String(co.company_name).trim().slice(0, 200) : 'not shared',
        monthly_revenue: co && co.monthly_revenue ? String(co.monthly_revenue).trim().slice(0, 100) : 'not shared',
        company_done: true
      };
      nextAction = 'save_website';
    }
  } else if (phase === 'awaiting_website') {
    const w = grab('website');
    if (w !== undefined) {
      const site = w && w.website ? String(w.website).trim().slice(0, 300) : 'none';
      leadInfo = { ...(leadInfo || {}), website: site, website_done: true };
      if (site.toLowerCase() === 'none') {
        leadInfo.company_asked = true;
        if (!text.includes('?')) text = (text ? text + ' ' : '') + cfg.noWebsiteQuestion;
      } else {
        nextAction = 'save_website';
      }
    }
  }
  // Strip any stray hidden blocks so the visitor never sees them
  text = text.replace(/<(slot|email|website|company|fetch_slots)>.*?<\/(slot|email|website|company|fetch_slots)>/gs, '').trim();
}

if (!text) {
  if (nextAction === 'fetch_slots') text = 'Great, let me pull up some times for you!';
  else if (nextAction === 'book_meeting') text = 'Perfect - locking that in now.';
  else if (nextAction === 'save_website') text = 'Thanks! ' + CONFIRM_INVITE;
  else text = 'Sorry, I hit a snag on my end - could you send that again?';
}

if (nextAction === 'save_website' && !/inbox|spam/i.test(text)) {
  text = text + ' ' + CONFIRM_INVITE;
}

return [{ json: { reply: text, nextAction, leadInfo, bookingInfo, slotsOffered, meetingBooked, cancelUrl, rescheduleUrl, availableWindowText, aiError: apiError } }];

// Input: Calendly /event_type_available_times response -> { collection: [ { status, start_time }, ... ] }
// Offers the earliest open slot on each of the next 3 weekdays, inside the configured hours.
const cfg = $('Set Workflow Parameters').first().json;
const httpResult = $input.first().json;
const parseData = $('Parse Reply and Identify Lead').first().json;
const timezone = cfg.displayTimezone;
const aiLine = parseData.reply;

const MIN_MINUTES = Number(cfg.earliestHour) * 60;
const MAX_MINUTES = Number(cfg.latestHour) * 60;

const failReply = (why) => [{
  json: {
    reply: `${aiLine} ${why} - I'll flag this to ${cfg.hostName} and they'll reach out to find a time that works.`,
    slotsOffered: null,
    meetingBooked: false,
    availableWindowText: null,
    leadInfo: parseData.leadInfo
  }
}];

const collection = (httpResult.collection || []).filter(s => {
  if (s.status !== 'available') return false;
  const hm = new Intl.DateTimeFormat('en-US', { timeZone: timezone, hour: 'numeric', minute: '2-digit', hourCycle: 'h23' }).format(new Date(s.start_time));
  const [h, m] = hm.split(':').map(Number);
  const total = h * 60 + m;
  return total >= MIN_MINUTES && total <= MAX_MINUTES;
});

if (collection.length === 0) return failReply("Looks like I'm having trouble pulling times right now");

const dayKey = new Intl.DateTimeFormat('en-CA', { timeZone: timezone });
const earliestByDay = new Map();
for (const s of collection) {
  const k = dayKey.format(new Date(s.start_time));
  if (!earliestByDay.has(k)) earliestByDay.set(k, s);
}

// Walk forward from tomorrow, skip weekends, take the earliest slot per day
const weekday = new Intl.DateTimeFormat('en-US', { timeZone: timezone, weekday: 'short' });
const top3 = [];
let cursor = new Date(Date.now() + 24 * 60 * 60 * 1000);
for (let i = 0; i < 30 && top3.length < 3; i++) {
  const d = weekday.format(cursor);
  if (d !== 'Sat' && d !== 'Sun') {
    const slot = earliestByDay.get(dayKey.format(cursor));
    if (slot) top3.push(slot);
  }
  cursor = new Date(cursor.getTime() + 24 * 60 * 60 * 1000);
}

if (top3.length < 3) return failReply("I'm not seeing enough open weekday slots right now");

const hours = top3.map(s => parseInt(new Intl.DateTimeFormat('en-US', { timeZone: timezone, hour: 'numeric', hourCycle: 'h23' }).format(new Date(s.start_time)), 10));
const label = h => `${h % 12 === 0 ? 12 : h % 12}:00 ${h >= 12 ? 'PM' : 'AM'}`;
const minH = Math.min(...hours);
const maxH = Math.max(...hours);
const availableWindowText = minH === maxH ? `around ${label(minH)}` : `between ${label(minH)} and ${label(maxH)}`;

const fmt = iso => new Intl.DateTimeFormat('en-US', { timeZone: timezone, weekday: 'long', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit', hour12: true, timeZoneName: 'short' }).format(new Date(iso));
const lines = top3.map(s => `- ${fmt(s.start_time)}`);

return [{
  json: {
    reply: `${aiLine}\n\nHere are some possible times:\n${lines.join('\n')}\n\nWhich one works best for you?`,
    slotsOffered: top3.map(s => s.start_time), // exact ISO strings - source of truth for booking
    meetingBooked: false,
    availableWindowText,
    leadInfo: parseData.leadInfo
  }
}];

// Input: Calendly POST /invitees response
const cfg = $('Set Workflow Parameters').first().json;
const bookingResult = $input.first().json;
const parseData = $('Parse Reply and Identify Lead').first().json;
const bookingInfo = parseData.bookingInfo;
const bookedIso = parseData.slotsOffered[bookingInfo.slot_index];
const bookedTimeDisplay = new Intl.DateTimeFormat('en-US', { timeZone: cfg.displayTimezone, weekday: 'long', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit', hour12: true, timeZoneName: 'short' }).format(new Date(bookedIso));

const reply = `You’re all set, ${bookingInfo.name}! Booked for ${bookedTimeDisplay} - the invite is on its way to ${bookingInfo.email} (check your spam folder too, just in case).\n\n${cfg.websiteQuestion}`;

const leadInfo = { ...(parseData.leadInfo || {}), name: bookingInfo.name, email: bookingInfo.email, website_asked: true, bookedTimeIso: bookedIso, bookedTimeDisplay };
const resource = bookingResult.resource || {};

return [{ json: { reply, slotsOffered: null, meetingBooked: true, bookedTimeIso: bookedIso, bookedTimeDisplay, name: bookingInfo.name, email: bookingInfo.email, leadInfo, cancelUrl: resource.cancel_url || null, rescheduleUrl: resource.reschedule_url || null } }];

