// Reads from Confirm Booking so a failed notification never blocks the visitor's confirmation
const c = $('Confirm Meeting Booking').first().json;
return [{ json: { reply: c.reply, slotsOffered: c.slotsOffered, meetingBooked: c.meetingBooked, leadInfo: c.leadInfo, cancelUrl: c.cancelUrl, rescheduleUrl: c.rescheduleUrl } }];

// Calendly rejected the booking: work out why and ask the visitor to fix it
const parseData = $('Parse Reply and Identify Lead').first().json;
const err = JSON.stringify($input.first().json || {}).toLowerCase();
const leadInfo = { ...(parseData.leadInfo || {}) };
let reply;
if (err.includes('email')) {
  delete leadInfo.email; // keep the chosen time, ask for the email again
  reply = 'Hmm, the calendar couldn\u2019t accept that email - could you double-check it and send it again?';
} else {
  delete leadInfo.selected_slot_index; // most likely the slot was just taken
  reply = 'That time just got taken - could you pick one of the other options instead?';
}
return [{ json: { reply, slotsOffered: parseData.slotsOffered, meetingBooked: false, leadInfo, availableWindowText: parseData.availableWindowText } }];

// Turns Gemini's response (or error) into one common shape
const r = $input.first().json;
const apiError = r?.error?.message || r?.error?.error?.message || (r?.name === 'AxiosError' ? r?.message : null) || null;
let text = '';
let finalError = apiError;
if (!apiError) {
  text = (r.candidates?.[0]?.content?.parts || []).map(p => p.text || '').join('').trim();
  if (!text) finalError = 'Gemini returned an empty response';
}
return [{ json: { content: finalError ? [] : [{ type: 'text', text }], error: finalError ? { message: finalError } : undefined, needsFallback: !!finalError } }];

// Turns Groq's response (or error) into the same shape as the Gemini branch
const r = $input.first().json;
const apiError = r?.error?.message || r?.error?.error?.message || (r?.name === 'AxiosError' ? r?.message : null) || null;
let text = '';
let finalError = apiError;
if (!apiError) {
  text = r.choices?.[0]?.message?.content || '';
  if (!text) finalError = 'Groq returned an empty response';
}
return [{ json: { content: finalError ? [] : [{ type: 'text', text }], error: finalError ? { message: finalError } : undefined } }];

// Builds a plain-text transcript of the latest turns for the team chat
const cfg = $('Set Workflow Parameters').first().json;
const replyText = $json.reply || '';
const history = $('Generate AI Prompt').first().json.messages || [];
const turns = [...history.slice(-9), { role: 'assistant', content: replyText }];

let usedFallback = false;
try { $('Normalize Groq Response').first(); usedFallback = true; } catch (e) { usedFallback = false; }

let text = (usedFallback ? '(answered by Groq fallback - Gemini failed)\n' : '') +
  'Conversation update:\n' +
  turns.map(m => (m.role === 'user' ? 'Visitor: ' : cfg.assistantName + ': ') + m.content).join('\n');

// Optional: show offered slots in your team's own timezone too
const slots = $json.slotsOffered;
if (cfg.teamTimezone && Array.isArray(slots) && slots.length) {
  const f = tz => new Intl.DateTimeFormat('en-US', { timeZone: tz, weekday: 'short', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit', hour12: true, timeZoneName: 'short' });
  text += '\n\nSlots offered (team time):\n' + slots.map(iso => `${f(cfg.displayTimezone).format(new Date(iso))} -> ${f(cfg.teamTimezone).format(new Date(iso))}`).join('\n');
}

return [{ json: { larkBody: { msg_type: 'text', content: { text } } } }];

