Name: {{ $('Parse Reply and Identify Lead').first().json.leadInfo.name || 'n/a' }}
Email: {{ $('Parse Reply and Identify Lead').first().json.leadInfo.email || 'n/a' }}
Website: {{ $('Parse Reply and Identify Lead').first().json.leadInfo.website || 'n/a' }}
Company: {{ $('Parse Reply and Identify Lead').first().json.leadInfo.company_name || 'n/a' }}
Monthly revenue: {{ $('Parse Reply and Identify Lead').first().json.leadInfo.monthly_revenue || 'n/a' }}
Meeting time: {{ $('Parse Reply and Identify Lead').first().json.leadInfo.bookedTimeDisplay || 'n/a' }}

Reschedule link: {{ $('Parse Reply and Identify Lead').first().json.rescheduleUrl || 'n/a' }}
Cancel link: {{ $('Parse Reply and Identify Lead').first().json.cancelUrl || 'n/a' }}
